//! ♻️ Original IO retirement preserves cancellation, recipient identity and the actual remaining wallet.
use super::*;
use semio_framework_value::retained_clone::RetainedCloneStep;
use semio_framework_value_native_owned::native_decoding::NativeDecodeRetirementRecipient;
use std::cell::Cell;
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap()}

#[test]
fn original_io_retirement_keeps_canceled_decoder_and_remaining_physical_wallet(){
 let f=fixture();let grant:RetainedCloneGrant=serde_json::from_value(f["grant"].clone()).unwrap();let receipt:RetainedCloneProgress=serde_json::from_value(f["receipt"].clone()).unwrap();let live=Cell::new(true);let calls=Cell::new(0);let mut progress=|_|{calls.set(calls.get()+1);live.get()};let mut recipient=NativeDecodeRetirementRecipient::new();let mut decode=NativeDecodeControl::new(64,&mut progress);decode.install_retirement_recipient(&mut recipient).unwrap();decode.charge(f["initialOwnedBytes"].as_u64().unwrap()as usize).unwrap();let ledger=decode.ledger_identity();let recipient=decode.retirement_recipient_identity();let mut run=IoRunControl::decoding(&mut decode,grant);live.set(false);assert_eq!(run.checkpoint().unwrap_err().kind,ValueRefusalKind::Canceled);
 for turn in 0..f["turns"].as_u64().unwrap(){
  let remaining=run.remaining_grant();let before=run.progress();let visited=Cell::new(false);
  for axis in 0..5{let mut denied=remaining;match axis{0=>denied.maximum_items+=1,1=>denied.maximum_copy_bytes+=1,2=>denied.maximum_capacity_bytes+=1,3=>denied.maximum_release_bytes+=1,_=>denied.maximum_depth+=1}let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||run.with_native_retirement(denied,|_|{visited.set(true);Ok(RetainedCloneStep::Progress(Default::default()))}));assert!(result.is_err());assert!(!visited.get());assert_eq!((born,released),(0,0));assert_eq!(run.progress(),before);}
  let hop=RetainedCloneGrant{maximum_items:receipt.copied_items,maximum_copy_bytes:receipt.copied_bytes,maximum_capacity_bytes:receipt.retained_capacity_bytes,maximum_release_bytes:receipt.released_bytes,maximum_depth:1};let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||run.with_native_retirement(hop,|original|{assert_eq!(original.ledger_identity(),ledger);assert_eq!(original.retirement_recipient_identity(),recipient);original.charge(receipt.retained_capacity_bytes)?;let mut bytes=Vec::<u8>::new();bytes.try_reserve_exact(3).unwrap();bytes.extend_from_slice(b"abc");assert_eq!(bytes.capacity(),3);drop(bytes);if turn==0{Ok(RetainedCloneStep::Progress(receipt))}else{Err(ValueError::literal(ValueRefusalKind::Canceled,"original cleanup refusal retains performed receipt").with_retained_progress(receipt))}}));assert_eq!((born,released),(receipt.retained_capacity_bytes,receipt.released_bytes));if turn==0{assert_eq!(result.unwrap().progress(),receipt)}else{assert_eq!(result.unwrap_err().retained_progress(),receipt)}assert_eq!(run.progress(),before.checked_add(receipt).unwrap());
 }
 assert_eq!(run.remaining_grant(),RetainedCloneGrant{maximum_depth:grant.maximum_depth,..Default::default()});assert_eq!(run.checkpoint().unwrap_err().kind,ValueRefusalKind::Canceled);drop(run);assert_eq!(decode.owned_bytes(),f["expectedOwnedBytes"].as_u64().unwrap()as usize);assert_eq!(decode.ledger_identity(),ledger);assert_eq!(decode.retirement_recipient_identity(),recipient);assert!(!live.get());assert!(calls.get()>0);eprintln!("[DEBUG] original IO retirement two paid turns, five-axis prebirth refusal, canceled semantic decoder, exact cumulative ledger, same recipient, actual heap and refused receipt settled");
}

#[test]
fn original_io_retirement_preserves_active_encoder_and_refuses_encoder_only_authority(){
 let f=fixture();let grant:RetainedCloneGrant=serde_json::from_value(f["grant"].clone()).unwrap();let decode_live=Cell::new(true);let encode_calls=Cell::new(0);let mut decode_callback=|_|decode_live.get();let mut encode_callback=|_|{encode_calls.set(encode_calls.get()+1);true};let mut recipient=NativeDecodeRetirementRecipient::new();let mut decode=NativeDecodeControl::new(64,&mut decode_callback);decode.install_retirement_recipient(&mut recipient).unwrap();let mut encode=NativeEncodeControl::new(64,&mut encode_callback);let ledger=decode.ledger_identity();let mut run=IoRunControl::new(&mut decode,&mut encode,grant);run.select(IoNativeDirection::Encode).unwrap();decode_live.set(false);let calls=encode_calls.get();run.with_native_retirement(grant,|original|{assert_eq!(original.ledger_identity(),ledger);Ok(RetainedCloneStep::Progress(Default::default()))}).unwrap();assert_eq!(run.direction(),IoNativeDirection::Encode);assert_eq!(encode_calls.get(),calls);drop(run);
 let mut run=IoRunControl::encoding(&mut encode,grant);let visited=Cell::new(false);let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||run.with_native_retirement(grant,|_|{visited.set(true);Ok(RetainedCloneStep::Progress(Default::default()))}));assert_eq!(result.unwrap_err().kind,ValueRefusalKind::UnsupportedOwner);assert!(!visited.get());assert_eq!((born,released),(0,0));assert_eq!(run.progress(),Default::default());eprintln!("[DEBUG] original IO retirement borrows actual decode beside active encoder, does not select or observe foreign phase, encoder-only authority refused before effects");
}
